export function accountT(lang: AppLanguage, key: AccountMessageKey, vars?: Record<string, string | number>): string {
  const raw = ACCOUNT_MESSAGES[lang]?.[key] ?? ACCOUNT_MESSAGES.en[key] ?? key;
  if (!vars) return raw;
  return Object.entries(vars).reduce(
    (s, [k, v]) => s.split('{' + k + '}').join(String(v)),
    raw,
  );
}
